@Timeout(70 * 1000)
@EnabledIfSystemProperty(named = "system.bootstrap.type", matches = "APP")
public class TestTag {

    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(1)
    void testAddInstanceTag(VertxTestContext testContext)
    {
        var id = ObjectConfigStore.getStore().getItemByIP("172.16.8.2");

        Assertions.assertNotNull(id,"device 172.16.8.2 should be provision");

        TestAPIUtil.get(OBJECT_API_ENDPOINT + "/instance-tags/" + id,testContext.succeeding(handler ->{

            var result = handler.bodyAsJsonObject().getJsonObject(RESULT);

            for(var instance : result) //will receive one instance
            {
                var items = result.getJsonArray(instance.getKey());

                for(var index = 0; index < items.size();index++)
                {
                    var item = items.getJsonObject(index);

                    if("63".equalsIgnoreCase(item.getString(AIOpsObject.OBJECT_NAME))) //adding tags in interface instance(object.name = 63)
                    {
                        item.put(INSTANCE_USER_TAG,new JsonArray().add("instanceTag1").add("instanceKey:value"));
                    }
                }

                TestAPIUtil.put(OBJECT_API_ENDPOINT + "/instances/" + id,result,testContext.succeeding(message -> testContext.verify(() -> {

                    Assertions.assertEquals(200, message.statusCode());

                    testContext.completeNow();
                })));
            }
        }));
    }

    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(2)
    void testGetInstanceTag(VertxTestContext testContext)
    {
        var id = ObjectConfigStore.getStore().getItemByIP("172.16.8.2");

        Assertions.assertNotNull(id,"device 172.16.8.2 should be provision");

        TestAPIUtil.get(OBJECT_API_ENDPOINT + "/instance-tags/" + id,testContext.succeeding(handler ->{

            var result = handler.bodyAsJsonObject().getJsonObject(RESULT);

            for(var instance : result)
            {
                var items = result.getJsonArray(instance.getKey());

                for(var index = 0; index < items.size();index++)
                {
                    var item = items.getJsonObject(index);

                    if("63".equalsIgnoreCase(item.getString(AIOpsObject.OBJECT_NAME)))
                    {
                        Assertions.assertTrue(item.containsKey(INSTANCE_USER_TAG));

                        Assertions.assertTrue(item.getJsonArray(INSTANCE_USER_TAG).contains("instanceTag1"));

                        Assertions.assertTrue(item.getJsonArray(INSTANCE_USER_TAG).contains("instanceKey:value"));

                        testContext.completeNow();
                    }
                    else
                    {
                        Assertions.assertFalse(item.containsKey(INSTANCE_USER_TAG));
                    }
                }
            }
        }));
    }

    @RepeatedIfExceptionsTest(suspend = 3000L)
